const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((res, err) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (Paraná River Delta approx. bbox)
    const geom = ee.Geometry.Rectangle([-60.9, -34.8, -57.8, -32.0], null, false);
    const areaKm2 = await getInfoAsync(geom.area().divide(1e6));
