    const end2019 = '2019-07-23'; // inclusive of Jul 22
    const start2020 = '2020-01-01';
    const end2020 = '2020-07-23';

    // 2. Data Acquisition & Check: MODIS Active Fire (MCD14DL) point detections
    const collectionId = 'MODIS/051/MCD14DL';
    let fc2019 = ee.FeatureCollection(collectionId)
      .filterBounds(geom)
      .filterDate(start2019, end2019);
    let fc2020 = ee.FeatureCollection(collectionId)
      .filterBounds(geom)
      .filterDate(start2020, end2020);

    const n2019 = await getInfoAsync(fc2019.size());
    const n2020 = await getInfoAsync(fc2020.size());

    // Handle Missing Data (C1)
    if ((n2019 === 0) || (n2020 === 0)) {
      console.log(`Region area (km2): ${areaKm2.toFixed(0)}`);
      console.log(`2019 hotspots: ${n2019}`);
      console.log(`2020 hotspots: ${n2020}`);
      console.log('C1: Empty Collection');
      return;
    }

    // 3. Processing: Not applicable (points, no cloud masking). No Valid Pixels (C2) not relevant.

    // 4. Calculation & Validation
    if (n2019 == null || n2020 == null || !isFinite(n2019) || !isFinite(n2020)) {
      console.log(`Region area (km2): ${areaKm2.toFixed(0)}`);
      console.log(`2019 hotspots: ${n2019}`);
      console.log(`2020 hotspots: ${n2020}`);
      console.log('C3: Calculation Failure');
      return;
    }

    const diff = n2020 - n2019;
    const ratio = n2019 > 0 ? (n2020 / n2019) : null;

    // 5. Output concise evidence (<=20 lines) and final answer
    console.log(`Region area (km2): ${Math.round(areaKm2)}`);
    console.log(`Dataset: MODIS MCD14DL (active fire detections)`);
    console.log(`2019 Jan1–Jul22 hotspots: ${n2019}`);
    console.log(`2020 Jan1–Jul22 hotspots: ${n2020}`);
    console.log(`Change (2020-2019): ${diff}${ratio !== null ? `, Ratio: ${ratio.toFixed(2)}x` : ''}`);

    if (ratio === null) {
      console.log('C3: Calculation Failure');
    } else if (n2020 > n2019) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (e) {
    // Any dataset, method, or server error
    console.log(`Error: ${e && e.message ? e.message : e}`);
    console.log('D');
  }
}

